const items = [...uris.matchAll(/'(["'^'"']+)'\\s+(\\S+)\\s+(\\d+)/g)];
await mkdir('/tmp/orbit-chromium-deps', { recursive: true });
await Promise.all(items.map(async ([, url, name]) => {
 const response = await fetch(url.replace('http:', 'https:'));
